function readCount(text) {
  try {
    const value = JSON.parse(text);
    return Object.hasOwn(value, 'count') ? value.count : null;
  } catch {
    return null;
  }
}

function parseArrayOrEmpty(text) {
  try {
    const value = JSON.parse(text);
    return Array.isArray(value) ? value : [];
  } catch {
    return [];
  }
}

